  const libRs = await readFile(libRsPath, 'utf8');
  publicModules = [...libRs.matchAll(/^\s*pub mod (\w+);/gm)].map((match) => match[1]);
} catch {
  errors.push(`could not read rust/src/lib.rs to enumerate the public module surface`);
}

